import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form, Alert, Button, Badge } from "react-bootstrap";
import "chartist/dist/chartist.min.css";

/* ===================== STYLE (Modern & Clean Design) ===================== */
const themeStyle = `
  .chart-scroll { overflow-x: auto; overflow-y: hidden; -webkit-overflow-scrolling: touch; }
  
  /* Main Card styling */
  .main-card {
    border: none !important;
    box-shadow: 0 15px 35px rgba(50,50,93,.1), 0 5px 15px rgba(0,0,0,.07) !important;
    border-radius: 1rem !important;
    overflow: hidden;
  }
  
  /* Modern Header */
  .history-header {
    background: #fff !important;
    border-bottom: 1px solid #e9ecef !important;
    padding: 25px 30px !important;
  }
  .history-header .card-title { 
    color: #32325d !important; 
    margin: 0 !important; 
    font-weight: 800; 
    font-size: 1.5rem; 
    letter-spacing: -0.5px;
  }

  /* Form Elements */
  .form-group-custom { margin-bottom: 0; }
  .form-label-custom {
    font-weight: 700;
    color: #5e72e4;
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 0.1em;
    margin-bottom: 10px;
    display: block;
  }
  .form-select-custom {
    border-radius: 12px !important;
    padding: 12px 18px !important;
    border: 1px solid #cad1d7 !important;
    font-size: 1rem !important;
    color: #525f7f !important;
    box-shadow: none !important;
    transition: all 0.2s ease;
  }
  .form-select-custom:focus {
    border-color: #5e72e4 !important;
    background-color: #fff !important;
    box-shadow: 0 0 0 3px rgba(94, 114, 228, 0.1) !important;
  }

  /* Graph elements */
  .ct-bar { cursor: pointer; transition: opacity 0.2s ease; }
  .ct-bar:hover { opacity: 0.8; }
  .legend-dot { width: 12px; height: 12px; border-radius: 50%; display: inline-block; margin-right: 8px; }
  
  /* Detail Chart Gradient Fill */
  .ct-series-a .ct-area {
    fill: url(#gradient) !important;
    fill-opacity: 0.2;
  }
  .ct-series-a .ct-line { stroke: #5e72e4; stroke-width: 3px; }
  .ct-series-a .ct-point { stroke: #5e72e4; stroke-width: 8px; }

  /* Empty State styling */
  .no-data-card {
    border: 2px dashed #e9ecef !important;
    background-color: #f8f9fe !important;
    border-radius: 1rem !important;
  }
`;

const CAMERA_MAP = { CAM01: "วิศวะ", CAM02: "วิทยาศาสตร์", CAM03: "ศิลปศาสตร์", CAM04: "PKY" };

function History() {
  const currentYearBE = new Date().getFullYear() + 543;
  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState((new Date().getMonth() + 1).toString().padStart(2, "0"));
  const [selectedYearBE, setSelectedYearBE] = useState(currentYearBE.toString());
  const [cameraId, setCameraId] = useState("CAM01");
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");

  const [rawFileData, setRawFileData] = useState({ labels: [], series: [[]] });
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });
  const [detailChart, setDetailChart] = useState(null); 
  const [selectedHour, setSelectedHour] = useState(null);
  const [isLoaded, setIsLoaded] = useState(false);

  const monthsThai = [
    { val: "01", name: "มกราคม" }, { val: "02", name: "กุมภาพันธ์" }, { val: "03", name: "มีนาคม" },
    { val: "04", name: "เมษายน" }, { val: "05", name: "พฤษภาคม" }, { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" }, { val: "08", name: "สิงหาคม" }, { val: "09", name: "กันยายน" },
    { val: "10", name: "ตุลาคม" }, { val: "11", name: "พฤศจิกายน" }, { val: "12", name: "ธันวาคม" },
  ];

  const timeOptions = Array.from({ length: 16 }, (_, i) => {
    const hour = (i + 7).toString().padStart(2, "0") + ":00";
    return <option key={hour} value={hour}>{hour}</option>;
  });

  const handleSearch = async () => {
    setIsLoaded(false);
    setDetailChart(null);
    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2, "0")}`;
    
    try {
      const res = await fetch(`http://localhost:3001/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`);
      const result = await res.json();

      if (result && result.labels && result.labels.length > 0) {
        setRawFileData(result);
        const bucket = {};
        result.labels.forEach((label, idx) => {
          const hour = label.split(":")[0].padStart(2, '0') + ":00";
          if (!bucket[hour]) bucket[hour] = { sum: 0, count: 0 };
          bucket[hour].sum += result.series[0][idx];
          bucket[hour].count += 1;
        });

        const labels = [], series = [];
        const startH = parseInt(startTime.split(":")[0]);
        const endH = parseInt(endTime.split(":")[0]);

        for (let i = startH; i <= endH; i++) {
          const h = i.toString().padStart(2, '0') + ":00";
          labels.push(h);
          series.push(bucket[h] ? Math.round(bucket[h].sum / bucket[h].count) : 0);
        }
        setChartState({ labels, series: [series] });
      } else {
        setChartState({ labels: [], series: [[]] });
        setRawFileData({ labels: [], series: [[]] });
      }
    } catch (err) { 
        console.error("Fetch error:", err);
        setChartState({ labels: [], series: [[]] });
    } finally { setIsLoaded(true); }
  };

  useEffect(() => { handleSearch(); }, [selectedDay, selectedMonth, selectedYearBE, cameraId, startTime, endTime]);

  const getDensityColor = (val) => {
    if (val >= 41) return "#f5365c"; 
    if (val >= 31) return "#fb6340"; 
    if (val >= 21) return "#ffd600"; 
    return "#2dce89"; 
  };

  const chartEvents = {
    draw: (data) => {
      if (data.type === "bar") {
        data.element.attr({ style: `stroke: ${getDensityColor(data.value.y)}; stroke-width: 25px;` });
        data.group.elem("text", { 
          x: data.x2, y: data.y2 - 12, 
          style: "font-size:12px; font-weight:800; text-anchor:middle; fill:#32325d; font-family: inherit;" 
        }).text(data.value.y);
      }
    },
    created: (context) => {
      if (!context.svg) return;
      context.svg._node.onclick = (e) => {
        const bar = e.target.closest('.ct-bar');
        if (!bar) return;
        const seriesGroup = bar.parentNode;
        const allBars = Array.from(seriesGroup.querySelectorAll('.ct-bar'));
        const index = allBars.indexOf(bar);
        if (index !== -1 && chartState.labels[index]) {
          const hourLabel = chartState.labels[index];
          const dLabels = [], dSeries = [];
          rawFileData.labels.forEach((l, i) => {
            if (l.startsWith(hourLabel.split(":")[0])) {
              dLabels.push(l);
              dSeries.push(rawFileData.series[0][i]);
            }
          });
          if (dLabels.length > 0) {
            setSelectedHour(hourLabel);
            setDetailChart({ labels: dLabels, series: [dSeries] });
          }
        }
      };
    }
  };

  return (
    <Container fluid className="py-5 bg-light min-vh-100">
      <style>{themeStyle}</style>
      
      {/* --- Main Control Card --- */}
      <Row className="justify-content-center mb-5">
        <Col lg="11">
          <Card className="main-card">
            <Card.Header className="history-header">
              <Row className="align-items-center">
                <Col><Card.Title as="h4">🔎 ค้นหาข้อมูลย้อนหลัง</Card.Title></Col>
                <Col xs="auto">
                  <Badge bg="primary" className="px-3 py-2 rounded-pill fs-6">
                    {CAMERA_MAP[cameraId]} | {startTime} - {endTime}
                  </Badge>
                </Col>
              </Row>
            </Card.Header>
            <Card.Body className="p-5">
              <Row className="g-4 align-items-end">
                {/* สถานที่ */}
                <Col md="4">
                  <Form.Group className="form-group-custom">
                    <Form.Label className="form-label-custom">📍 เลือกสถานที่</Form.Label>
                    <Form.Select value={cameraId} onChange={(e) => setCameraId(e.target.value)} className="form-select-custom">
                      {Object.entries(CAMERA_MAP).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
                    </Form.Select>
                  </Form.Group>
                </Col>
                
                {/* วันที่ */}
                <Col md="5">
                  <Form.Group className="form-group-custom">
                    <Form.Label className="form-label-custom">📅 เลือกวันที่</Form.Label>
                    <div className="d-flex gap-2">
                      <Form.Select value={selectedDay} onChange={(e) => setSelectedDay(e.target.value)} className="form-select-custom flex-grow-1">{Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>{i+1}</option>)}</Form.Select>
                      <Form.Select value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="form-select-custom flex-grow-2">{monthsThai.map(m=><option key={m.val} value={m.val}>{m.name}</option>)}</Form.Select>
                      <Form.Select value={selectedYearBE} onChange={(e) => setSelectedYearBE(e.target.value)} className="form-select-custom flex-grow-1"><option value={currentYearBE}>{currentYearBE}</option><option value={currentYearBE-1}>{currentYearBE-1}</option></Form.Select>
                    </div>
                  </Form.Group>
                </Col>

                {/* ช่วงเวลา */}
                <Col md="3">
                  <Form.Group className="form-group-custom">
                    <Form.Label className="form-label-custom">⏱️ ช่วงเวลา</Form.Label>
                    <div className="d-flex align-items-center gap-2">
                      <Form.Select value={startTime} onChange={(e) => setStartTime(e.target.value)} className="form-select-custom">{timeOptions}</Form.Select>
                      <span className="text-muted fw-bold">ถึง</span>
                      <Form.Select value={endTime} onChange={(e) => setEndTime(e.target.value)} className="form-select-custom">{timeOptions}</Form.Select>
                    </div>
                  </Form.Group>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* --- กราฟรายชั่วโมง --- */}
      {isLoaded && chartState.labels.length > 0 ? (
        <Row className="justify-content-center mb-5">
          <Col lg="11">
            <Card className="main-card">
              <Card.Body className="p-5">
                <div className="d-flex justify-content-between align-items-center mb-5 flex-wrap gap-2">
                  <h5 className="mb-0 text-dark fw-bold">📊 กราฟรายชั่วโมง (เฉลี่ย)</h5>
                  <div className="d-flex gap-4 flex-wrap bg-white p-2 px-3 rounded-pill shadow-inner border">
                    <div className="small fw-bold text-muted"><span className="legend-dot" style={{background:'#2dce89'}}></span> ปกติ (0-20)</div>
                    <div className="small fw-bold text-muted"><span className="legend-dot" style={{background:'#ffd600'}}></span> เริ่มเยอะ (21-30)</div>
                    <div className="small fw-bold text-muted"><span className="legend-dot" style={{background:'#fb6340'}}></span> เยอะ (31-40)</div>
                    <div className="small fw-bold text-muted"><span className="legend-dot" style={{background:'#f5365c'}}></span> เยอะมาก (41+)</div>
                  </div>
                </div>
                <div className="chart-scroll"><div style={{ width: "100%", minWidth: "800px", height: "420px" }}>
                  <ChartistGraph 
                    data={chartState} 
                    type="Bar" 
                    options={{ low: 0, fullWidth: true, chartPadding: { top: 30, right: 20, bottom: 0, left: 10 } }} 
                    listener={chartEvents} 
                  />
                </div></div>
                <p className="text-center text-muted small mt-4 bg-light d-inline-block px-3 py-1 rounded-pill">💡 จิ้มที่แท่งกราฟเพื่อดูรายละเอียดระดับรายนาที</p>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      ) : (
        isLoaded && (
          <Row className="justify-content-center">
            <Col lg="11">
              <Card className="no-data-card py-5 text-center">
                <Card.Body>
                  <div className="mb-4 display-3 text-muted">📁</div>
                  <h3 className="text-muted fw-bold mb-3">ไม่พบข้อมูลสถิติในวันที่เลือก</h3>
                  <Alert variant="info" className="d-inline-block px-4 shadow-sm border-0 rounded-pill">
                    {selectedDay} {monthsThai.find(m => m.val === selectedMonth)?.name} {selectedYearBE} | {startTime} - {endTime}
                  </Alert>
                </Card.Body>
              </Card>
            </Col>
          </Row>
        )
      )}

      {/* --- กราฟรายละเอียดรายนาที --- */}
      {detailChart && (
        <Row className="justify-content-center">
          <Col lg="11">
            <Card className="main-card border-top border-primary border-4">
              <Card.Header className="bg-white border-0 d-flex justify-content-between align-items-center p-4 px-5">
                <h5 className="mb-0 font-weight-bold text-primary">📈 รายละเอียดรายนาที ช่วงเวลา {selectedHour} น.</h5>
                <Button variant="link" className="text-danger fw-bold" onClick={() => setDetailChart(null)}>ปิด</Button>
              </Card.Header>
              <Card.Body className="p-5 pt-0">
                <div className="chart-scroll">
                  <div style={{ width: "100%", minWidth: "1200px", height: "380px" }}>
                    <ChartistGraph 
                        data={detailChart} 
                        type="Line" 
                        options={{ 
                            low: 0, showArea: true, fullWidth: true,
                            axisX: { labelInterpolationFnc: (value, index) => index % 5 === 0 ? value : null, offset: 60 }
                        }} 
                    />
                    {/* SVG Gradient definition */}
                    <svg width="0" height="0">
                      <defs>
                        <linearGradient id="gradient" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="0%" stopColor="#825ee4" stopOpacity="0.8"/>
                          <stop offset="100%" stopColor="#5e72e4" stopOpacity="0"/>
                        </linearGradient>
                      </defs>
                    </svg>
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
